library(irGSEA);writeLines(deparse(body(irGSEA.integrate)),'/mnt/BioData/bio/wangmingyuan/liver_fibrosis_HCC_audit_20261016/end_to_end_20261020/continuation_expanded_irGSEA_v1/integrate_source_used.R');for(q in list.files('/mnt/BioData/bio/wangmingyuan/liver_fibrosis_HCC_audit_20261016/end_to_end_20261020/continuation_expanded_irGSEA_v1',pattern='integrated.rds',recursive=TRUE,full.names=TRUE)){a<-readRDS(q);cat(q,'\n');str(a,max.level=2);walk<-function(v,n){if(is.data.frame(v)){write.table(v,file.path(dirname(q),paste0('export_',gsub('[^A-Za-z0-9_]','_',n),'.tsv')),sep='\t',quote=FALSE,row.names=FALSE)}else if(is.list(v)){for(k in names(v))walk(v[[k]],paste(n,k,sep='_'))}};walk(a,'integration')}